import{_ as t,o,c as d,a2 as c}from"./chunks/framework.CWWEQfK7.js";const h=JSON.parse('{"title":"把 Ershu 接入 MCP 客户端","description":"创建受限 MCP 密钥，把客户端连接到 Ershu，并用一条可核验的工具链读取项目上下文。","frontmatter":{"page_id":"guide-connect-mcp","description":"创建受限 MCP 密钥，把客户端连接到 Ershu，并用一条可核验的工具链读取项目上下文。"},"headers":[],"relativePath":"guide/connect-mcp.md","filePath":"guide/connect-mcp.md","lastUpdated":1786290726000}'),r={name:"guide/connect-mcp.md"};function a(i,e,s,l,_,n){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="把-ershu-接入-mcp-客户端" tabindex="-1">把 Ershu 接入 MCP 客户端 <a class="header-anchor" href="#把-ershu-接入-mcp-客户端" aria-label="Permalink to &quot;把 Ershu 接入 MCP 客户端&quot;">​</a></h1><p>Ershu 的 MCP 服务是面向开发智能体的只读入口。它不修改仓库，也不负责生成文档；它读取 Core 中的项目、权限、文档、索引和关系查询，并为每次请求应用用户权限与 MCP 密钥范围。</p><p>本页不绑定某一款客户端。不同客户端的配置字段不同，但都需要相同的连接信息。</p><h2 id="接入前确认三件事" tabindex="-1">接入前确认三件事 <a class="header-anchor" href="#接入前确认三件事" aria-label="Permalink to &quot;接入前确认三件事&quot;">​</a></h2><ol><li>MCP 进程正在运行，默认地址是 <code>http://127.0.0.1:8001/mcp/</code>。</li><li>你已经能在 Ershu 网页中读取目标项目。密钥不会扩大你的项目权限。</li><li>目标仓库已有可用事实。目录可以按当前源码读取；代码索引、关系和文档的完整程度取决于分析与刷新状态。</li></ol><p>可以先打开 <code>http://127.0.0.1:8001/health</code>。返回 <code>{&quot;status&quot;:&quot;ok&quot;}</code> 只说明进程存活，不代表数据库、权限或工具调用已经成功。</p><h2 id="创建最小权限密钥" tabindex="-1">创建最小权限密钥 <a class="header-anchor" href="#创建最小权限密钥" aria-label="Permalink to &quot;创建最小权限密钥&quot;">​</a></h2><p>在 Ershu 网页的 MCP 密钥管理页创建密钥时，需要填写名称，并选择以下一种范围：</p><ul><li>仅允许一个或多个明确项目；</li><li>允许当前用户可读的全部项目。</li></ul><p>还可以设置未来的过期时间。更稳妥的默认做法是只选当前任务需要的项目，并设置到期时间。服务只在创建响应中返回完整密钥；之后的列表只保留前缀、范围、到期时间和使用记录，因此应在创建时保存到客户端的密钥存储中。</p><p>密钥被撤销、过期，或原用户失去项目读取权限后，调用会被拒绝。创建和撤销都会写入审计记录。</p><h2 id="填写客户端连接信息" tabindex="-1">填写客户端连接信息 <a class="header-anchor" href="#填写客户端连接信息" aria-label="Permalink to &quot;填写客户端连接信息&quot;">​</a></h2><p>把以下信息映射到客户端的 Streamable HTTP 配置。字段名以你的客户端文档为准，不要直接假定它使用某个固定 JSON 结构。</p><table tabindex="0"><thead><tr><th>信息</th><th>值</th></tr></thead><tbody><tr><td>传输方式</td><td>Streamable HTTP</td></tr><tr><td>服务地址</td><td><code>http://127.0.0.1:8001/mcp/</code></td></tr><tr><td>请求头</td><td><code>Authorization: Bearer &lt;MCP_KEY&gt;</code></td></tr></tbody></table><p>生产环境应使用 HTTPS，并把 <code>/mcp/</code> 原样转发到 MCP 进程的 <code>8001</code> 端口。外部 Host 和 Origin 必须进入 <code>MCP_ALLOWED_HOSTS</code> 与 <code>MCP_ALLOWED_ORIGINS</code>。不要把 MCP 请求发送到 API 的 <code>8000</code> 端口。</p><h2 id="用-get-server-info-完成第一次验证" tabindex="-1">用 <code>get_server_info</code> 完成第一次验证 <a class="header-anchor" href="#用-get-server-info-完成第一次验证" aria-label="Permalink to &quot;用 `get_server_info` 完成第一次验证&quot;">​</a></h2><p>连接后先调用 <code>get_server_info</code>。成功结果包含：</p><ul><li><code>service</code>，当前应为 <code>ershu-mcp</code>；</li><li>已安装的包版本；</li><li>构建使用的完整提交号；</li><li><code>identity_status</code>；</li><li>当前注册的工具名。</li></ul><p>生产进程只有在包版本可读、<code>MCP_BUILD_COMMIT</code> 是完整 40 位提交号时才允许启动。开发环境可以没有这两项，此时 <code>identity_status</code> 会是 <code>unavailable</code>，不能把它当作已核验的构建身份。</p><p>当前服务应列出 27 个工具。若连接成功但没有工具，或清单与预期构建不一致，应先检查服务版本和代理路径，不要继续依据不明版本开展工作。</p><h2 id="一条可靠的项目阅读顺序" tabindex="-1">一条可靠的项目阅读顺序 <a class="header-anchor" href="#一条可靠的项目阅读顺序" aria-label="Permalink to &quot;一条可靠的项目阅读顺序&quot;">​</a></h2><p>项目参数可以使用 UUID、slug 或唯一的可读名称。名称有歧义时改用 slug 或 UUID。</p><ol><li>用 <code>list_projects</code> 发现当前密钥可见的项目。</li><li>用 <code>resolve_project</code> 确认项目引用，再用 <code>list_project_repositories</code> 取得仓库编号和新鲜度。</li><li>用 <code>get_project_overview</code> 建立项目级方向，用 <code>list_repository_documents</code> 和 <code>list_document_sections</code> 选择要读的章节。</li><li>用 <code>list_repository_tree</code> 和 <code>list_repository_code_index</code> 找到源码路径和符号。</li><li>用 <code>find_project_change_surface</code> 或 <code>trace_project_runtime_flow</code> 缩小范围。</li><li>最后用 <code>read_code_context</code> 读取关键源码，核对精确行为。</li></ol><p>文档结果的 <code>authority</code> 可能是 <code>secondary</code>，适合导航和解释；源码、契约与结构化事实标为 <code>source_derived</code>，更适合支撑精确结论。任何时候都要同时查看提交、新鲜度、覆盖范围和截断标记。</p><h2 id="_27-个工具怎样分工" tabindex="-1">27 个工具怎样分工 <a class="header-anchor" href="#_27-个工具怎样分工" aria-label="Permalink to &quot;27 个工具怎样分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>工具</th></tr></thead><tbody><tr><td>服务与项目发现</td><td><code>get_server_info</code>、<code>list_projects</code>、<code>resolve_project</code>、<code>list_project_repositories</code></td></tr><tr><td>更新事实并跟踪任务</td><td><code>refresh_repository_facts</code>、<code>get_run_status</code></td></tr><tr><td>阅读项目文档</td><td><code>get_project_overview</code>、<code>list_repository_documents</code>、<code>list_document_sections</code>、<code>get_document</code>、<code>get_document_section</code></td></tr><tr><td>浏览源码与索引</td><td><code>list_repository_tree</code>、<code>list_repository_code_index</code>、<code>read_code_context</code></td></tr><tr><td>搜索与关系分析</td><td><code>search_project_context</code>、<code>query_internal_api</code>、<code>query_project_graph</code>、<code>find_project_change_surface</code>、<code>trace_project_runtime_flow</code></td></tr><tr><td>读取消费者契约</td><td><code>list_project_contracts</code>、<code>get_consumer_contract</code>、<code>list_public_interfaces</code>、<code>get_public_interface</code>、<code>get_contract_schema</code>、<code>query_consumer_contracts</code>、<code>diff_consumer_contracts</code>、<code>suggest_consumer_work</code></td></tr></tbody></table><p>分页工具的 <code>limit</code> 通常是 <code>1</code> 到 <code>100</code>，偏移量从 <code>0</code> 开始。目录深度最多为 <code>10</code>，单次目录结果最多保留 <code>500</code> 项；源码读取单次最多 <code>400</code> 行。消费者契约查询的实际服务上限是 <code>50</code>。这些边界用于控制上下文大小，不表示结果天然完整。</p><h2 id="什么时候刷新事实" tabindex="-1">什么时候刷新事实 <a class="header-anchor" href="#什么时候刷新事实" aria-label="Permalink to &quot;什么时候刷新事实&quot;">​</a></h2><p>如果仓库的新鲜度显示过期，并且当前用户有项目维护权限，可以调用 <code>refresh_repository_facts</code>。它只排入以下四类更新：</p><ul><li>目录树；</li><li>代码索引；</li><li>知识关系；</li><li>搜索索引。</li></ul><p>它不会生成或改写 AI 文档。工具返回任务编号后，用 <code>get_run_status</code> 观察 <code>queued</code>、<code>running</code>、完成或失败状态。状态查询本身不会创建新任务。</p><h2 id="常见失败怎样判断" tabindex="-1">常见失败怎样判断 <a class="header-anchor" href="#常见失败怎样判断" aria-label="Permalink to &quot;常见失败怎样判断&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>先检查什么</th></tr></thead><tbody><tr><td><code>401</code> 或认证失败</td><td>请求头是否精确使用 <code>Bearer</code>；密钥是否过期、撤销或复制不完整</td></tr><tr><td>项目找不到</td><td>密钥范围、用户项目权限，以及名称是否有歧义</td></tr><tr><td>浏览器能开 <code>/health</code>，客户端仍连不上</td><td>客户端是否使用 <code>/mcp/</code>，代理是否保留路径，Host 和 Origin 是否允许</td></tr><tr><td>搜索结果降级</td><td>返回的检索模式、<code>degraded</code>、<code>fallback_used</code> 和搜索索引状态</td></tr><tr><td>关系结果很少</td><td><code>data_status</code>、覆盖范围、限制和截断标记；有界候选不是完整清单</td></tr><tr><td>文档与源码不一致</td><td>先看文档提交和 <code>authority</code>，再用 <code>read_code_context</code> 核对当前源码</td></tr></tbody></table><p>连接成功的最终判据不是健康页，而是：客户端能认证调用 <code>get_server_info</code>，能列出一个确实有权限的项目，并能从该项目读取带仓库提交信息的目录或源码结果。</p><blockquote><p>主要源码位置：<code>mcp/src/ershu/mcp/server.py</code>、<code>mcp/src/ershu/mcp/tool_runtime.py</code>、<code>mcp/src/ershu/mcp/runtime_identity.py</code>、<code>api/src/ershu/api/services/mcp_keys.py</code>。</p></blockquote>',35)])])}const u=t(r,[["render",a]]);export{h as __pageData,u as default};
